import pytest
import requests

@pytest.mark.parametrize("pet_id, expected_status", [
    (1, 200),  # Assuming pet with ID 1 exists
    (999999, 404),  # Assuming pet with ID 999999 does not exist
    ("invalid", 400),  # Invalid ID format
])
def test_get_pet_by_id(api_client, valid_api_key, pet_id, expected_status):
    """
    Test the GET /v2/pet/{petId} endpoint with various pet IDs.
    """
    headers = {"api_key": valid_api_key}
    response = api_client.make_request(f"v2/pet/{pet_id}", headers=headers)
    assert response.status_code == expected_status

    if response.status_code == 200:
        pet_data = response.json()
        assert "name" in pet_data
        assert "photoUrls" in pet_data
        assert isinstance(pet_data["photoUrls"], list)

def test_get_pet_by_id_invalid_key(api_client, invalid_api_key):
    """
    Test the GET /v2/pet/{petId} endpoint with an invalid API key.
    """
    headers = {"api_key": invalid_api_key}
    response = api_client.make_request("v2/pet/1", headers=headers)
    assert response.status_code == 401  # Unauthorized

def test_get_pet_by_id_missing_key(api_client):
    """
    Test the GET /v2/pet/{petId} endpoint without an API key.
    """
    response = api_client.make_request("v2/pet/1")
    assert response.status_code == 401  # Unauthorized

